<?php
require_once __DIR__ . '/includes/bootstrap.php';
$items = cart_products(); $subtotal = cart_total($items); $shipping = $subtotal > 0 && $subtotal < 100 ? 7.00 : 0.00;
$title = 'Your bag — Rally'; require __DIR__ . '/includes/header.php';
?>
<section class="section-wrap cart-page"><div class="page-heading"><span class="eyebrow">YOUR RALLY BAG</span><h1>The good stuff.</h1></div>
<?php if (!$items): ?><div class="empty-state"><p>Your bag is taking a breather.</p><a class="button button-dark" href="/#shop">Explore the collection <span>↗</span></a></div>
<?php else: ?><div class="cart-layout"><div class="cart-items"><?php foreach ($items as $item): ?><article class="cart-item"><a href="/product.php?id=<?= (int) $item['id'] ?>"><img src="<?= e($item['image_url']) ?>" alt="<?= e($item['name']) ?>"></a><div class="cart-item-info"><span class="eyebrow"><?= e(strtoupper($item['category'])) ?></span><a class="product-name" href="/product.php?id=<?= (int) $item['id'] ?>"><?= e($item['name']) ?></a><span class="product-category"><?= money($item['price']) ?> each</span><div class="cart-row-actions"><form action="/cart-action.php" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update"><input type="hidden" name="product_id" value="<?= (int) $item['id'] ?>"><label class="quantity-label">Qty <input type="number" name="quantity" min="1" max="<?= min(99, (int) $item['stock']) ?>" value="<?= (int) $item['quantity'] ?>"></label><button class="inline-button">Update</button></form><form action="/cart-action.php" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= (int) $item['id'] ?>"><button class="inline-button muted">Remove</button></form></div></div><strong><?= money($item['line_total']) ?></strong></article><?php endforeach; ?></div>
<aside class="order-summary"><h2>Summary</h2><div><span>Subtotal</span><span><?= money($subtotal) ?></span></div><div><span>Shipping</span><span><?= $shipping ? money($shipping) : 'Free' ?></span></div><div class="summary-total"><span>Total</span><strong><?= money($subtotal + $shipping) ?></strong></div><p><?= $subtotal >= 100 ? 'You unlocked free shipping.' : 'Free shipping when you spend $100.' ?></p><a class="button button-dark full-button" href="/checkout.php">Continue to checkout <span>↗</span></a><a class="continue-link" href="/#shop">← Keep shopping</a></aside></div><?php endif; ?></section>
